class Solution {
    public int semiOrderedPermutation(int[] nums) {
        int n = nums.length;
        int posOne = -1;
        int posN = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] == 1) {
                posOne = i;
            }
            if (nums[i] == n) {
                posN = i;
            }
        }
        int moves = posOne + (n - 1 - posN);
        if (posOne > posN) {
            moves--;
        }
        return moves;
    }
}

class Solution {
    public int semiOrderedPermutation(int[] nums) {
        int moves = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 1) {
                while (i > 0) {
                    int temp = nums[i];
                    nums[i] = nums[i - 1];
                    nums[i - 1] = temp;
                    i--;
                    moves++;
                }
                break;
            }
        }
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == nums.length) {
                while (i < nums.length - 1) {
                    int temp = nums[i];
                    nums[i] = nums[i + 1];
                    nums[i + 1] = temp;
                    i++;
                    moves++;
                }
                break;
            }
        }
        return moves;
    }
}

class Solution {
    public int semiOrderedPermutation(int[] nums) {
        int beforeOne = 0;
        while (nums[beforeOne] != 1) {
            beforeOne++;
        }

        int posLargest = nums.length - 1;
        int afterLargest = 0;
        while (nums[posLargest] != nums.length) {
            posLargest--;
            afterLargest++;
        }

        int moves = beforeOne + afterLargest;
        if (posLargest < beforeOne) {
            moves--;
        }
        return moves;
    }
}
